// Package graph contains the resolver implementation for the mock GraphQL API.
// This file is hand-written (not regenerated by gqlgen) and holds the Resolver
// struct, seed data initialization, and helper functions for filtering,
// pagination and copying.
package graph

import (
	"maps"
	"mockapi/graph/model"
	"slices"
	"strconv"
	"strings"
	"sync"
)

// Resolver is the root resolver that implements the gqlgen ResolverRoot interface.
// It holds all application state in-memory: a list of todos and users, seeded
// on first access.
//
// Concurrency invariant: gqlgen resolves the root fields of one query in
// parallel and serves requests concurrently (the example SDKs' batch samples
// do exactly that), so every resolver takes mu via lock() before touching the
// store, and returns clones rather than the stored pointers — gqlgen marshals
// the returned value after the resolver (and the lock) is gone, while a
// concurrent mutation may be editing the stored record.
type Resolver struct {
	mu     sync.Mutex
	seeded bool
	todos  []*model.Todo
	users  []*model.User
	// nextTodoID / nextUserID only ever grow, so an ID is never reused after
	// a delete (deriving it from len() handed out duplicate IDs).
	nextTodoID int
	nextUserID int
}

// pingResponse is the fixed answer to the `ping` query; samples print it.
const pingResponse = "pong from gqlgenapi"

// Defaults and keys for the `fail` query's error.
const (
	defaultFailMessage = "fail called"
	defaultFailCode    = "MOCK_FAILURE"
	// errorCodeExtension is the key in a GraphQL error's extensions object.
	errorCodeExtension = "code"
	// errorCodeNotFound tags errors for a referenced record that does not exist.
	errorCodeNotFound = "NOT_FOUND"
)

// Typed node IDs for the `node` query are "<Type>:<id>". Todo and user IDs
// overlap ("1" is both), so the type prefix is what makes them global.
const (
	nodeIDSeparator = ":"
	nodeTypeTodo    = "Todo"
	nodeTypeUser    = "User"
)

// todoCursorPrefix forms the synthetic Relay cursor "cursor-<id>".
const todoCursorPrefix = "cursor-"

// lock acquires the store lock, seeds the store on first use, and returns the
// unlock function for the caller to defer.
func (r *Resolver) lock() func() {
	r.mu.Lock()
	r.seedLocked()
	return r.mu.Unlock
}

// seedLocked populates the store once: two users (Alice as User, Bob as
// Admin) and two demo todos. Caller must hold mu.
func (r *Resolver) seedLocked() {
	if r.seeded {
		return
	}
	r.seeded = true
	r.users = []*model.User{
		{ID: "1", Name: "Alice", Role: model.RoleUser},
		{ID: "2", Name: "Bob", Role: model.RoleAdmin},
	}
	r.todos = []*model.Todo{
		{
			ID:        "1",
			Text:      "Try the ping query",
			Done:      false,
			Tags:      []string{"demo", "ping"},
			User:      r.users[0],
			CreatedAt: "2025-01-15T09:30:00Z",
			// Metadata is the schema's free-form `Metadata` scalar, which
			// gqlgen maps to map[string]any — a framework-boundary type.
			Metadata: map[string]any{"source": "seed", "priority_label": "low"},
		},
		{
			ID:        "2",
			Text:      "Create your first todo",
			Done:      false,
			Tags:      []string{"demo"},
			User:      r.users[1],
			CreatedAt: "2025-01-16T14:00:00Z",
		},
	}
	// Seed one self-reference so Todo.parent has data to show.
	r.todos[1].Parent = r.todos[0]
	r.nextTodoID = len(r.todos)
	r.nextUserID = len(r.users)
}

// newTodoID returns the next unused todo ID. Caller must hold mu.
func (r *Resolver) newTodoID() string {
	r.nextTodoID++
	return strconv.Itoa(r.nextTodoID)
}

// newUserID returns the next unused user ID. Caller must hold mu.
func (r *Resolver) newUserID() string {
	r.nextUserID++
	return strconv.Itoa(r.nextUserID)
}

// cloneUser returns a copy safe to hand to gqlgen outside the lock. Email is
// only ever replaced, never written through, so sharing the pointer is safe.
func cloneUser(u *model.User) *model.User {
	if u == nil {
		return nil
	}
	cp := *u
	return &cp
}

// cloneTodo returns a copy safe to hand to gqlgen outside the lock, including
// its user and its parent chain. Priority is only ever replaced, never written
// through. The parent chain is finite: only the seed sets Parent, and no
// mutation can create a cycle.
func cloneTodo(t *model.Todo) *model.Todo {
	if t == nil {
		return nil
	}
	cp := *t
	cp.Parent = cloneTodo(t.Parent)
	cp.Tags = slices.Clone(t.Tags)
	cp.Metadata = maps.Clone(t.Metadata)
	cp.User = cloneUser(t.User)
	return &cp
}

// paginate applies offset/limit to n items and returns the [start,end) window.
// A nil input, a zero limit or a negative limit means "no limit"; an offset at
// or past the end yields an empty window (never a wrap back to the start).
func paginate(n int, p *model.PaginationInput) (start, end int) {
	start, end = 0, n
	if p == nil {
		return start, end
	}
	if p.Offset > 0 {
		start = min(int(p.Offset), n)
	}
	if p.Limit > 0 {
		end = min(start+int(p.Limit), n)
	}
	return start, end
}

// todoPageLocked filters the store, applies pagination and returns clones of
// the page, the window's start offset, and the filtered total. Caller must
// hold mu.
func (r *Resolver) todoPageLocked(filter *model.TodoFilter, pagination *model.PaginationInput) (page []*model.Todo, start, total int) {
	var matched []*model.Todo
	for _, t := range r.todos {
		if matchesTodoFilter(t, filter) {
			matched = append(matched, t)
		}
	}
	start, end := paginate(len(matched), pagination)
	page = make([]*model.Todo, 0, end-start)
	for _, t := range matched[start:end] {
		page = append(page, cloneTodo(t))
	}
	return page, start, len(matched)
}

// matchesTodoFilter checks whether a todo satisfies all criteria in the given filter.
// Returns true if filter is nil (no filtering). Each non-nil filter field is applied
// as an AND condition: text substring match, done status, minimum priority, and tag membership.
func matchesTodoFilter(t *model.Todo, f *model.TodoFilter) bool {
	if f == nil {
		return true
	}
	if f.TextContains != nil && !containsIgnoreCase(t.Text, *f.TextContains) {
		return false
	}
	if f.Done != nil && t.Done != *f.Done {
		return false
	}
	// MinPriority requires the todo to have a priority set and >= the threshold.
	if f.MinPriority != nil {
		if t.Priority == nil || *t.Priority < *f.MinPriority {
			return false
		}
	}
	// HasTag requires at least one of the todo's tags to match exactly.
	if f.HasTag != nil {
		found := false
		for _, tag := range t.Tags {
			if tag == *f.HasTag {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}

// containsIgnoreCase performs a case-insensitive substring check.
// Returns true if substr is empty (matches everything).
func containsIgnoreCase(s, substr string) bool {
	if substr == "" {
		return true
	}
	return strings.Contains(strings.ToLower(s), strings.ToLower(substr))
}
